@lru_cache(maxsize=8)
def render_sample_svg(slug):
    if slug not in _PAGE_DATA:
        raise KeyError(slug)
    raw=zlib.decompress(base64.b85decode(_PAGE_DATA[slug].encode("ascii")))
    width,height,spans=json.loads(raw)
    if not (0 < width <= 1000 and 0 < height <= 1200 and len(spans) < 200):
        raise ValueError("Invalid preview metadata")
    lines=[
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" viewBox="0 0 {width} {height}" role="img" aria-label="A sample layout based on one page of a HER POV PDF">',
        f'<title>HER POV — original PDF page preview — {escape(slug)}</title>',
        '<desc>Text and line positioning are extracted from one original guide page; typography uses browser fallback fonts, so it may differ slightly from the purchased PDF.</desc>',
        f'<rect width="{width}" height="{height}" fill="#fffdf9"/>'
    ]
    for x,y,size,color,font_style,content in spans:
        font='Georgia,serif' if font_style.startswith("S") else 'Arial,sans-serif'
        weight='bold' if "B" in font_style else 'normal'
        style='italic' if "I" in font_style else 'normal'
        lines.append(
            f'<text x="{x}" y="{y}" fill="#{color}" font-family="{font}" font-size="{size}" font-weight="{weight}" font-style="{style}">{escape(content)}</text>'
        )
    lines.append('</svg>')
    return "".join(lines).encode("utf-8")
